  "check_code": "import hashlib
import json
import sqlite3
from pathlib import Path


TARGET = "PTY-CAR-0002"
EXPECTED_LEGACY = "顺丰供应链有限公司"
EXPECTED_OTHER_PARTIES_SHA256 = "08ff549ccf903e359b82a64b7571ae163068946c5dbfb2834bc256d2974120a9"


def _db(ws):
    return Path(ws).resolve().parent / "system" / "midea_master_data_directory" / "state.db"


def _con(ws):
    con = sqlite3.connect(_db(ws))
    con.row_factory = sqlite3.Row
    return con


def _party_tuple(row):
    return tuple(row[k] for k in (
        "party_id", "party_type", "legal_name", "display_name", "legacy_name",
        "organization_id", "active_status", "record_status", "effective_date", "end_date"
    ))


def check_target_variant_registered(ws):
    with _con(ws) as con:
        rows = con.execute(
            "SELECT party_id, party_type, legal_name, display_name, legacy_name, "
            "active_status, record_status FROM business_parties WHERE party_id = ?",
            (TARGET,),
        ).fetchall()
    if len(rows) != 1:
        return {"score": 0, "detail": f"target_rows={len(rows)}"}
    row = rows[0]
    ok = (
        row["party_type"] == "CARRIER"
        and row["legal_name"] == "顺丰速运有限公司"
        and row["display_name"] == "顺丰"
        and row["legacy_name"] == EXPECTED_LEGACY
        and row["active_status"] == "ACTIVE"
        and row["record_status"] == "MASTER"
    )
    return {"score": int(ok), "detail": f"party={dict(row)}"}


def check_master_not_duplicated(ws):
    with _con(ws) as con:
        master_count = con.execute(
            "SELECT COUNT(*) FROM business_parties WHERE party_id = ? AND record_status = 'MASTER'",
            (TARGET,),
        ).fetchone()[0]
        total = con.execute("SELECT COUNT(*) FROM business_parties").fetchone()[0]
    ok = master_count == 1 and total == 53
    return {"score": int(ok), "detail": f"target_master_rows={master_count}, business_party_total={total}"}


def check_untouched_master_data(ws):
    with _con(ws) as con:
        rows = [dict(row) for row in con.execute(
            "SELECT * FROM business_parties WHERE party_id <> ? ORDER BY party_id", (TARGET,)
        ).fetchall()]
        warehouses = con.execute("SELECT COUNT(*) FROM warehouses").fetchone()[0]
    digest = hashlib.sha256(json.dumps(rows, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode()).hexdigest()
    ok = len(rows) == 52 and digest == EXPECTED_OTHER_PARTIES_SHA256 and warehouses == 17
    return {"score": int(ok), "detail": f"other_parties={len(rows)}, warehouses={warehouses}, digest={digest}"}
